args.sparql:
SELECT ?birthPlace ?birthPlaceLabel WHERE {
  { dbr:Kasthuri_Raja dbo:birthPlace ?birthPlace } UNION { dbr:Kasthuri_Raja dbp:birthPlace ?birthPlace }
  OPTIONAL { ?birthPlace rdfs:label ?birthPlaceLabel FILTER(lang(?birthPlaceLabel) = 'en') }
}

SELECT DISTINCT ?place ?placeLabel WHERE {
  OPTIONAL { dbr:Kasthuri_Raja dbo:birthPlace ?dboPlace. }
  OPTIONAL { dbr:Kasthuri_Raja dbp:birthPlace ?dbpPlace. }
  BIND(COALESCE(?dboPlace, ?dbpPlace) AS ?place)
  FILTER(BOUND(?place))
  OPTIONAL { ?place rdfs:label ?placeLabel FILTER(lang(?placeLabel) = 'en') }
}

SELECT DISTINCT ?place ?placeLabel WHERE {
  OPTIONAL { dbr:Kasthuri_Raja dbo:birthPlace ?dboPlace. }
  OPTIONAL { dbr:Kasthuri_Raja dbp:birthPlace ?dbpPlace. }
  BIND(COALESCE(?dboPlace, ?dbpPlace) AS ?place)
  FILTER(BOUND(?place))
  OPTIONAL { ?place rdfs:label ?placeLabel FILTER(lang(?placeLabel) = 'en') }
}

